/// The rider app's parsing of the ride lifecycle, against the server's own
/// captured responses.
///
/// WHY THIS FILE EXISTS
/// --------------------
/// Authentication was pinned to a generated contract after the driver app
/// shipped reading `data['access']` for a field the server calls `token`.
/// Everything after login had the same exposure and no such pin: the fare
/// quote, the trip record, history, ratings and the refusals, all parsed by
/// two Flutter apps from envelopes nobody had captured.
///
/// `test/contracts/ride_contracts.json` is generated by
/// `tests/test_ride_contract_capture.py` from real view output. If a view's
/// shape changes, that file changes and these tests fail -- and nobody can
/// "fix" them by editing a fixture to match the app.
///
/// Regenerate:
///   cd SaaradhiGo-backend && pytest tests/test_ride_contract_capture.py
///   cp contracts/ride_contracts.json ../SaaradhiGo-mobile/test/contracts/
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:saaradhigo_rider/state/ride_notifier.dart';

Map<String, dynamic> _contract() {
  final file = File('test/contracts/ride_contracts.json');
  if (!file.existsSync()) {
    fail(
      'test/contracts/ride_contracts.json is missing. Regenerate it with '
      'tests/test_ride_contract_capture.py in the backend.',
    );
  }
  return jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
}

Map<String, dynamic> _endpoint(String name) {
  final endpoints = _contract()['endpoints'] as Map<String, dynamic>;
  final entry = endpoints[name];
  if (entry == null) {
    fail(
      'The contract has no "$name". Captured: '
      '${endpoints.keys.join(", ")}',
    );
  }
  return (entry as Map).cast<String, dynamic>();
}

Map<String, dynamic> _data(String name) =>
    ((_endpoint(name)['body'] as Map)['data'] as Map).cast<String, dynamic>();

void main() {
  group('the contract file', () {
    test('exists and names its generator', () {
      expect(_contract()['_README'], contains('GENERATED'));
      expect(_contract()['endpoints'], isA<Map>());
    });
  });

  group('the trip status vocabulary', () {
    test('this app maps EVERY status the server can send', () {
      // The defect this prevents has already happened once: the rider app did
      // not map 'reached', so a rider whose driver was waiting outside saw a
      // blank screen on recovery. A status added server-side now fails here
      // instead.
      final vocabulary = (_contract()['trip_status_vocabulary'] as List)
          .cast<String>();

      expect(vocabulary, isNotEmpty);
      final unmapped = vocabulary
          .where((code) => rideStatusFromBackendCode(code) == null)
          .toList();

      expect(
        unmapped,
        isEmpty,
        reason:
            'the server can send these and this app would leave the '
            'rider looking at whatever was on screen before: $unmapped',
      );
    });

    test('every status maps to a distinct rider-visible state', () {
      // Two server statuses collapsing into one app state is how 'reached'
      // became invisible even after it was mapped.
      final vocabulary = (_contract()['trip_status_vocabulary'] as List)
          .cast<String>();
      final mapped = {
        for (final code in vocabulary) code: rideStatusFromBackendCode(code),
      };

      expect(mapped['requested'], isNot(mapped['accepted']));
      expect(mapped['accepted'], isNot(mapped['reached']));
      expect(mapped['reached'], isNot(mapped['in_progress']));
      expect(mapped['in_progress'], isNot(mapped['completed']));
      expect(mapped['completed'], isNot(mapped['cancelled']));
    });

    test('an unknown status returns null rather than a wrong guess', () {
      expect(rideStatusFromBackendCode('teleported'), isNull);
      expect(rideStatusFromBackendCode(''), isNull);
    });
  });

  group('the fare quote', () {
    test('carries the fields the rider UI needs, under these names', () {
      final data = _data('ride_estimate_fare');

      // The quote a rider is shown. `currency` is here because a rupee
      // amount rendered with the wrong symbol was a real defect.
      for (final field in [
        'estimated_fare',
        'currency',
        'distance_km',
        'duration_min',
        'fare_breakdown',
      ]) {
        expect(
          data.containsKey(field),
          isTrue,
          reason: 'the quote has no "$field"; the rider UI reads it',
        );
      }
    });

    test('the server validates the distance it was given', () {
      // `validated_km` is the server's own measurement. A client-claimed
      // distance is not what the fare is computed from, and the app must not
      // present its own number as authoritative.
      final data = _data('ride_estimate_fare');

      expect(data.containsKey('validated_km'), isTrue);
      expect(
        data.containsKey('pricing_source'),
        isTrue,
        reason:
            'the rider-visible quote should be traceable to a rate '
            'card or a fallback',
      );
    });

    test(
      'an unserved area is a 400 with an error envelope, not an empty quote',
      () {
        final entry = _endpoint('ride_estimate_fare_outside_zone');

        expect(entry['status_code'], 400);
        final body = (entry['body'] as Map).cast<String, dynamic>();
        expect(body['status'], 'error');
        expect(body.containsKey('error'), isTrue);
        final error = (body['error'] as Map).cast<String, dynamic>();
        expect(
          error['message'],
          isNotNull,
          reason: 'the rider has to be told the area is not served',
        );
      },
    );
  });

  group('the trip record', () {
    test('carries the fields the rider screen reads', () {
      final data = _data('ride_trip_detail_rider');

      for (final field in [
        'id',
        'status',
        'pickup_address',
        'destination_address',
        'driver_name',
      ]) {
        expect(
          data.containsKey(field),
          isTrue,
          reason: 'trip detail has no "$field"',
        );
      }
    });

    test('its status is a value this app maps', () {
      final status = _data('ride_trip_detail_rider')['status'] as String;

      expect(
        rideStatusFromBackendCode(status),
        isNotNull,
        reason: 'the server sent "$status" and this app cannot place it',
      );
    });

    test('another rider is refused, and the app must handle that status', () {
      // Object-level authorization. A rider reading another rider's trip
      // would see a pickup address, a destination, and on some payloads the
      // OTP that starts the trip.
      final entry = _endpoint('ride_trip_detail_denied_other_rider');

      expect(entry['status_code'], anyOf(403, 404));
      final body = (entry['body'] as Map).cast<String, dynamic>();
      expect(body['status'], 'error');
    });
  });

  group('history', () {
    test('is paginated, under the names the app pages with', () {
      final data = _data('ride_history_rider');

      expect(data.containsKey('results'), isTrue);
      expect(data.containsKey('count'), isTrue);
      expect(
        data.containsKey('next'),
        isTrue,
        reason: 'the app decides whether to fetch another page from this',
      );
    });
  });

  group('rating a trip', () {
    test('the success envelope carries the identifiers the app echoes', () {
      final data = _data('ride_rate_trip');

      expect(data.containsKey('rating_id'), isTrue);
      expect(data['trip_id'], isNotNull);
      expect(data['score'], isNotNull);
    });

    test('rating twice is refused with a 409, which the UI must not retry', () {
      final entry = _endpoint('ride_rate_trip_duplicate');

      expect(entry['status_code'], 409);
      final body = (entry['body'] as Map).cast<String, dynamic>();
      expect(body['status'], 'error');
    });
  });

  group('SOS', () {
    test('returns an identifier the rider can be shown', () {
      // A reference number is what makes an SOS confirmation meaningful
      // rather than a reassurance.
      final data = _data('sos_create');

      expect(data.containsKey('sos_id'), isTrue);
      expect(_endpoint('sos_create')['status_code'], anyOf(200, 201));
    });
  });

  group('nothing in these envelopes leaks what it should not', () {
    test('no trip payload carries a password, a token or an FCM token', () {
      final endpoints = _contract()['endpoints'] as Map<String, dynamic>;

      for (final entry in endpoints.entries) {
        final text = jsonEncode(entry.value).toLowerCase();
        for (final leak in ['password', 'fcm_token', 'refresh_token']) {
          expect(
            text.contains(leak),
            isFalse,
            reason: '${entry.key} carries "$leak"',
          );
        }
      }
    });
  });
}
